-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الإبداع في حل المشكلات الهندسية","passage":"لاحظت طالبة أن المخططات الورقية تتعرض للتلف داخل ورشة التصميم، فوضعت ثلاثة تصورات لحافظة مناسبة، ثم صنعت نموذجًا من مواد آمنة واختبرته وعدلته. يظهر الإبداع بوصفه سلسلة ملاحظة وتجريب وتقييم، لا مجرد فكرة جذابة. النص أصلي من ضاديوم لا يقتبس القراءة المقررة.","prompt":"ما الخطوة التي سبقت تعديل التصميم؟","correct":"اختبار النموذج","w1":"إهمال المشكلة","w2":"توزيع الحافظة قبل فحصها","w3":"إلغاء البدائل","practice":"اكتب وصفًا لمشكلة في مكتب أو مختبر هندسي، واقترح حلين ومعيارًا موضوعيًا لاختبارهما."},{"n":2,"skill":"التعجب بصيغتين قياسيتين","passage":"«ما أجملَ النظامَ!» تعجب على صيغة «ما أفعَلَه» وفيها «النظامَ» مفعول به منصوب. «أجمِلْ بالنظام!» صيغة «أفعِلْ به» والغاية إظهار الإعجاب. لا تُصاغ كل صفة مباشرة من فعلها؛ فلصياغة التعجب القياسي شروط صرفية.","prompt":"ما صيغة «ما أجمل النظام»؟","correct":"ما أفعله","w1":"أداة نفي","w2":"صيغة استفهام فقط","w3":"أسلوب نداء","practice":"كوّن جملتي تعجب من مثال إداري وهندسي، ثم بيّن الأداة وضبط الاسم المتعجب منه."},{"n":3,"skill":"سرد مشكلة واتخاذ قرار","passage":"في قصة تدريبية تعطل برنامج الرسم قبل تسليم المشروع، فبحث الفريق عن نسخة محفوظة، واستشار المشرف، وأعاد بناء الجزء المفقود. يتتابع السرد من التمهيد إلى العقدة ثم الحل، وتدعم الروابط الزمنية وضوح الأحداث. هذا المثال مستقل لا ينقل قصة الكتاب.","prompt":"ما العقدة الرئيسة في القصة؟","correct":"تعطل برنامج الرسم قبل التسليم","w1":"بدء اليوم الدراسي","w2":"وجود مشرف","w3":"إنجاز نسخة احتياطية","practice":"اكتب قصة قصيرة من عشرة أسطر عن مشكلة في عمل جماعي، بمقدمة وعقدة وخطوات حل وخاتمة."},{"n":4,"skill":"مقومات النجاح في العمل","passage":"راجع مسؤول جودة قائمة فحص قبل إقرار تنفيذ مخطط هندسي، فكشف قياسًا غير صحيح وأعاد التصحيح إلى المصمم. نجاح المشروع هنا مرتبط بالانتباه للتفاصيل ووضوح المسؤولية والتعاون، لا بالعجلة أو إخفاء الخطأ. لا يمثل هذا المثال نص القراءة الأصلي.","prompt":"أي إجراء حال دون استمرار خطأ المخطط؟","correct":"مراجعة قائمة الفحص وتصحيح القياس","w1":"تجاهل التقرير","w2":"اعتماد المخطط بلا اختبار","w3":"تحميل الخطأ لطرف آخر","practice":"اكتب فقرة حجاجية عن عامل نجاح مهني، تتضمن موقفًا ودليلًا ونتيجة قابلة للملاحظة."},{"n":5,"skill":"الجملتان الاسمية والفعلية","passage":"«المخططُ واضحٌ» جملة اسمية تتكون من مبتدأ وخبر، و«راجعَ المهندسُ المخططَ» جملة فعلية تتكون من فعل وفاعل ومفعول به. يبرز التركيب الأول حالة المخطط، والثاني حدث المراجعة، ولا يصح الخلط بين الخبر والفاعل.","prompt":"أي جملة فعلية في الأمثلة؟","correct":"راجع المهندس المخطط","w1":"المخطط واضح","w2":"التصميم دقيق","w3":"النتيجة صحيحة","practice":"اكتب ثلاث جمل اسمية وثلاث فعلية تصف العمل الإداري أو الهندسي، ثم حدد الأركان."},{"n":6,"skill":"الوصف المكاني الدقيق","passage":"يدخل الزائر مكتب التصميم من باب واسع، ويقع مكتب الاستقبال عن اليمين، وتتوزع شاشات الرسم في صفين، وتُحفظ المستندات في خزائن مرقمة. الترتيب المكاني يساعد القارئ على تصور المكان، ويجب الفصل بين الملاحظة والرأي الشخصي.","prompt":"ما التفصيل الذي يوضح نظام حفظ المستندات؟","correct":"خزائن مرقمة","w1":"وقت الاستراحة","w2":"درجة الطالب","w3":"عنوان التقرير","practice":"اكتب وصفًا من سبع جمل لمكتب أو مختبر مستخدمًا علاقات الاتجاه والمسافة وإجراء سلامة واحدًا."},{"n":7,"skill":"المعنى الإنساني للسعادة في العمل","passage":"قد يشعر العامل بالرضا حين يرى أثر عمله النافع، لكن ذلك لا يعني أن كل وظيفة تخلو من مشقة. في نموذج أصلي تعاون موظفان لإنجاز خدمة لمراجع، ثم راجعا تجربتهما لتحسين الوقت والجودة. يرتبط الرضا بالإنجاز والتعاون ولا ينقل النص الرسمي «العمل سعادة».","prompt":"ما سبب شعور الموظفين بالإنجاز في النموذج؟","correct":"إتمام خدمة نافعة مع التعاون","w1":"تجاهل المراجعين","w2":"إخفاء الأخطاء","w3":"إلغاء تقييم العمل","practice":"بعد قراءة النص المقرر استخرج دليلًا صحيحًا على رأي الكاتب، ثم قارن ذلك بموقف مستقل عن معنى العمل."},{"n":8,"skill":"كان وأخواتها وأثرها","passage":"في «المكتبُ منظّمٌ» مبتدأ وخبر مرفوعان. وبعد دخول «كان» نقول «كان المكتبُ منظّمًا»، فيبقى اسم كان مرفوعًا ويصير خبرها منصوبًا. و«أصبح التقريرُ جاهزًا» مثال آخر لناسخ فعلي.","prompt":"ما إعراب «منظمًا» في «كان المكتب منظمًا»؟","correct":"خبر كان منصوب","w1":"اسم كان مرفوع","w2":"فاعل","w3":"حال في جملة فعلية","practice":"حوّل أربع جمل اسمية إلى جمل تدخل عليها كان أو أصبح، ثم أعرب الاسم والخبر."},{"n":9,"skill":"حوار نقدي عن الذكاء الاصطناعي","passage":"اقترح طالب استخدام الذكاء الاصطناعي لتلخيص مستند طويل، ونبّه آخر إلى ضرورة مراجعة المخرجات والتحقق من الأرقام وعدم إدخال بيانات خاصة بلا إذن. اتفقا على استخدام أداة مساعدة مع تدقيق بشري، لا تسليم قرار نهائي للنظام.","prompt":"ما الضمان الأساسي الذي اتفق عليه الطالبان؟","correct":"مراجعة المخرجات وحماية البيانات","w1":"نشر بيانات الجميع","w2":"الاعتماد على الملخص دون تحقق","w3":"إلغاء دور المعلم","practice":"اكتب حوارًا من ثماني مداخلات عن استخدام آمن للذكاء الاصطناعي في التعليم أو الإدارة، يتضمن منفعة ومخاطرة وضابطًا."},{"n":10,"skill":"تحليل الشعر دون اختلاق أبيات","passage":"تحليل قصيدة «أوال مهد الحب والجمال» يتطلب الرجوع إلى أبياتها الأصلية والتحقق من اسم الشاعر وشواهد الصور والعاطفة. مثال نثري مستقل: «يحمل الميناء القديم ذكريات الناس والعمل والألفة». يساعد المثال على فهم صلة المكان بالذاكرة، ولا يُنسب إلى القصيدة.","prompt":"ما العلاقة التي يبرزها النص النثري المستقل؟","correct":"صلة المكان بذاكرة السكان","w1":"غياب التاريخ","w2":"تشابه كل الموانئ","w3":"انعدام العاطفة","practice":"ارجع إلى أبيات القصيدة الأصلية، ثم وثق بيتًا وصورة فنية وعاطفة دون اختراع شاهد."},{"n":11,"skill":"إغناء الجملة بالمتممات الأولى","passage":"«راجعَ المديرُ الخطةَ» جملة فعلية واضحة الفعل والفاعل والمفعول. ويمكن القول «راجع المديرُ الخطةَ صباحًا في المكتب» لإضافة ظرف زمان وجار ومجرور يدل على المكان. تزوّد المتممات القارئ بمعلومات محددة.","prompt":"ما الكلمة التي تعين وقت مراجعة الخطة؟","correct":"صباحًا","w1":"الخطةَ","w2":"المديرُ","w3":"راجعَ","practice":"وسّع أربع جمل في سياق إداري بظرف وجار ومجرور ومفعول به، ثم حدد وظيفة كل متمم."},{"n":12,"skill":"حوار وطني يقترح عملًا","passage":"قال طالب: «أريد أن نخدم وطننا بتنظيم حملة لخفض الهدر في المدرسة». أجاب زميله: «نبدأ بقياس الاستهلاك، ثم نعرض النتائج على الإدارة». يعبر الحوار عن الانتماء من خلال مبادرة يمكن متابعة أثرها، دون مبالغة في ادعاء نتائج لم تُقَس بعد.","prompt":"أي خطوة تسبق ادعاء نجاح الحملة؟","correct":"قياس الاستهلاك وعرض النتائج","w1":"الاكتفاء بالشعارات","w2":"تجاهل الإدارة","w3":"اختلاق أرقام","practice":"أنشئ حوارًا قصيرًا يقترح مبادرة وطنية بمهام وزمن ومؤشر نجاح وأسلوب محترم."},{"n":13,"skill":"الحلم وخطة الإنجاز","passage":"حلمت متدربة بابتكار تطبيق يساعد الطلاب على ترتيب جداولهم، فاستطلعت احتياجات زملائها وأعدت نموذجًا بسيطًا واختبرته، ثم سجلت ملاحظاتهم لتطويره. يميز النص الأصلي بين حلم عام وخطوات عملية، ولا يمثل أحداث القراءة المدرسية.","prompt":"ما الإجراء الذي أتاح تطوير النموذج؟","correct":"تسجيل ملاحظات المستخدمين","w1":"تجاهل الطلاب","w2":"إلغاء التجربة","w3":"البدء بالإعلان قبل الفحص","practice":"اكتب قصة نجاح متخيلة بخمس مراحل واقعية، مع عقبة وتعديل مبني على الملاحظات."},{"n":14,"skill":"إغناء الجملة بالمتممات الثانية","passage":"«رسمَ المهندسُ التصميمَ بدقةٍ على الحاسوبِ» تحتوي مفعولًا به «التصميمَ» وجارًا ومجرورًا يصفان الكيفية والأداة في السياق. لا تعد كل كلمة بعد الفعل مفعولًا به، وتختلف مواقع الظرف والحال والمجرور.","prompt":"ما المفعول به في الجملة؟","correct":"التصميمَ","w1":"بدقةٍ","w2":"الحاسوبِ","w3":"المهندسُ","practice":"اكتب خمس جمل فعلية واستخدم فيها مفعولًا به وحالًا وظرفًا وجارًا ومجرورًا، مع تحليل دور كل عنصر."},{"n":15,"skill":"نقاش مدروس للزراعة الذكية","passage":"ناقش فريق فكرة استخدام حساس لقياس رطوبة التربة في مزرعة تعليمية. توقّع أحدهم تقليل الري الزائد، وطلب الآخر تجربة تقارن استهلاك الماء قبل إقرار الفائدة. يميز الحوار بين الفرضية والدليل، ولا يدعي نتائج بحثية غير متاحة.","prompt":"ما الذي يجعل فائدة الحساس قابلة للتحقق؟","correct":"تجربة مقارنة استهلاك الماء","w1":"تكرار الفكرة دون قياس","w2":"إغلاق المشروع","w3":"الاعتماد على إعلان تسويقي","practice":"اكتب حوارًا من ست مداخلات عن أمن الغذاء والزراعة الذكية يضم فرضية وخطة اختبار وتحفظًا."},{"n":16,"skill":"فهم الوطنية من سلوك مدني","passage":"في مثال أصلي شارك طلاب في تنظيم الكتب بمكتبة عامة، وتحققوا من احتياجات الزوار قبل توزيع الأدوار. الوطنية هنا ممارسة للمسؤولية واحترام المكان العام لا مجرد وصف عاطفي؛ ولا يمثل المثال نص «من معاني الوطنية» المقرر.","prompt":"ما السلوك الذي جسّد المسؤولية الوطنية؟","correct":"خدمة المكتبة العامة وتنظيمها","w1":"ترك العمل الجماعي","w2":"عدم سؤال الزوار","w3":"نقل الكتب بلا خطة","practice":"بعد قراءة النص الأصلي استخرج فكرة وشاهدًا موثقًا، ثم اقترح نشاطًا تطوعيًا ومعيارًا لقياس أثره."},{"n":17,"skill":"الهمزة المتوسطة على السطر أو النبرة","passage":"تتحدد كتابة الهمزة المتوسطة بمقارنة حركتها وحركة ما قبلها، مع قواعد خاصة. في «سُئِلَ» كتبت على نبرة لقوة الكسرة، وفي «مُؤْمِن» على واو لأن الضمة أقوى من السكون، وفي «رَأْس» على ألف لأن الفتحة أقوى من السكون.","prompt":"على أي كرسي كتبت الهمزة في «سُئِل»؟","correct":"على نبرة","w1":"على واو","w2":"على السطر","w3":"على ألف","practice":"صنف اثنتي عشرة كلمة بهمزة متوسطة، مع ذكر حركة الهمزة وما قبلها وسبب اختيار الكرسي."},{"n":18,"skill":"حوار الانتماء والعمل المشترك","passage":"في جلسة مدرسية اقترح متعلم عرضًا لتاريخ الابتكارات في البحرين، واقترح آخر دعوة متخصصين لمناقشة أعمالهم. اتفقا على توثيق المصادر واستئذان الضيوف قبل نشر الصور، فارتبط الانتماء بالمعرفة واحترام الخصوصية.","prompt":"ما الشرط الذي اتفقا عليه قبل نشر الصور؟","correct":"الحصول على إذن الضيوف","w1":"نشرها بلا سؤال","w2":"إلغاء توثيق المصادر","w3":"اختلاق شهادات","practice":"أنشئ حوارًا من ثماني مداخلات عن مشروع مدرسي يخدم المجتمع ويحترم المصادر والخصوصية."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=10
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='44c1dfd0-27ec-41b6-bee7-a4576a582ad5'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 811 — اللغة العربية للمسار الإداري والتكنولوجي - الهندسي' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_ADMIN_ENG_G10_T1_ARAB811_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_ADMIN_ENG_G10_T1_ARAB811_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_ADMIN_ENG_G10_T1_ARAB811_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_ADMIN_ENG_G10_T1_ARAB811_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;